export function projectLonLat(longitude: number, latitude: number): { x: number; y: number } {
  const lon = Math.max(-180, Math.min(180, longitude));
  const lat = Math.max(-90, Math.min(90, latitude));
  const absLat = Math.abs(lat);
  const idxFloat = absLat / 5;
  const idx = Math.min(17, Math.floor(idxFloat));
  const t = idxFloat - idx;
  const aa = ROBINSON_AA[idx] + (ROBINSON_AA[idx + 1] - ROBINSON_AA[idx]) * t;
  const bb = ROBINSON_BB[idx] + (ROBINSON_BB[idx + 1] - ROBINSON_BB[idx]) * t;
  return {
    x: MAP_WIDTH / 2 + (lon / 180) * 344 * aa,
    y: MAP_HEIGHT / 2 - Math.sign(lat) * 174.5 * bb,
  };
}

